import { test } from "node:test";
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin, type ToolResult } from "../src/plugin.ts";

test("handlers run sequentially in subscription order, async included", async () => {
  const bus = new HookBus();
  const order: string[] = [];
  bus.on("e", async () => {
    await new Promise((r) => setTimeout(r, 20));
    order.push("slow");
  });
  bus.on("e", () => order.push("fast"));
  await bus.emit("e", null);
  assert.deepEqual(order, ["slow", "fast"]);
});

test("emit resolves only after the last handler finished", async () => {
  const bus = new HookBus();
  let done = false;
  bus.on("e", async () => {
    await new Promise((r) => setTimeout(r, 10));
    done = true;
  });
  await bus.emit("e", null);
  assert.equal(done, true);
});

test("a throwing handler rejects emit with the same error and stops later handlers", async () => {
  const bus = new HookBus();
  const boom = new Error("boom");
  const ran: string[] = [];
  bus.on("e", () => ran.push("a"));
  bus.on("e", () => {
    throw boom;
  });
  bus.on("e", () => ran.push("c"));
  await assert.rejects(bus.emit("e", null), (err) => err === boom);
  assert.deepEqual(ran, ["a"]);
});

test("a rejecting async handler rejects emit with the same error", async () => {
  const bus = new HookBus();
  const boom = new Error("async boom");
  let later = false;
  bus.on("e", async () => {
    throw boom;
  });
  bus.on("e", () => {
    later = true;
  });
  await assert.rejects(bus.emit("e", null), (err) => err === boom);
  assert.equal(later, false);
});

test("self-unsubscribe during emit does not stop the others and applies from next emit", async () => {
  const bus = new HookBus();
  const ran: string[] = [];
  let offSelf = () => {};
  offSelf = bus.on("e", () => {
    ran.push("self");
    offSelf();
  });
  bus.on("e", () => ran.push("other"));
  await bus.emit("e", null);
  assert.deepEqual(ran, ["self", "other"]);
  assert.equal(bus.count("e"), 1);
  await bus.emit("e", null);
  assert.deepEqual(ran, ["self", "other", "other"]);
});

test("unsubscribing another handler during emit still runs it in that emit", async () => {
  const bus = new HookBus();
  const ran: string[] = [];
  let offB = () => {};
  bus.on("e", () => {
    offB();
  });
  offB = bus.on("e", () => ran.push("b"));
  await bus.emit("e", null);
  assert.deepEqual(ran, ["b"]);
  assert.equal(bus.count("e"), 1);
});

test("handlers subscribed during emit do not run in that emit", async () => {
  const bus = new HookBus();
  const ran: string[] = [];
  bus.on("e", () => {
    ran.push("a");
    bus.on("e", () => ran.push("late"));
  });
  await bus.emit("e", null);
  assert.deepEqual(ran, ["a"]);
  await bus.emit("e", null);
  assert.deepEqual(ran, ["a", "a", "late"]);
});

test("audit plugin: notice once, redact, then log in order", async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  const first: ToolResult = { tool: "bash", output: "run password=hunter2 now" };
  await bus.emit("tool.after", first);
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "bash: run password=[redacted] now",
  ]);
  assert.equal(first.output, "run password=[redacted] now");
  const second: ToolResult = { tool: "read", output: "ok" };
  await bus.emit("tool.after", second);
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "bash: run password=[redacted] now",
    "read: ok",
  ]);
  assert.equal(bus.count("tool.after"), 2);
});
